package chart

// The chart's content test: the facts the chart is built on, read off
// disk and held to the service and to the repository's own files.
//
// ## What this test is for
//
// `chart/` is generated by `caf gen chart`, whose source is in another
// repository, and it is the artifact the substrate's Argo Application
// syncs. Nothing else checks that the generated facts still agree with
// the service: that the chart's name is the service's, that its version
// is the tag the Application pins, that the container port is the port
// the Dockerfile exposes, that the readiness path is the fleet's
// contract. Each of those is a seam, and a seam that drifts is a deploy
// that runs the wrong image on the wrong port behind a probe that
// waits on a path nothing serves.
//
// ## Why the assertions are structural
//
// Every helper in chart.go refuses rather than under-reads, and every
// assertion below navigates to the fact it names. A test that would
// pass against an empty chart/templates/ is not a test: with the chart
// absent, parseFile fails on the first read, and with the chart present
// but a fact missing, the navigation fails on the missing key. Both
// directions are proven red in this file's own first run — see the
// packet report for the red-then-green record.
//
// This test needs no database: the chart is files, and files are what
// it reads.

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// chartRoot is the repository's chart directory, resolved from this
// test's own location so the proof runs from any working directory.
func chartRoot(t *testing.T) string {
	t.Helper()
	root, err := resolveRoot()
	if err != nil {
		t.Fatalf("resolve chart root: %v", err)
	}
	return root
}

// mustParse reads one file of the chart and parses it, failing the test
// if either step comes back with less than the file holds.
func mustParse(t *testing.T, root, name string) yamlMap {
	t.Helper()
	doc, err := parseFile(filepath.Join(root, name))
	if err != nil {
		t.Fatalf("parse %s: %v", name, err)
	}
	return doc
}

// mustChild navigates m → key and returns the value as a string.
func mustChild(t *testing.T, m yamlMap, key string) string {
	t.Helper()
	v, err := child(m, key)
	if err != nil {
		t.Fatalf("key %q: %v", key, err)
	}
	s, err := scalarString(v, key)
	if err != nil {
		t.Fatalf("key %q: %v", key, err)
	}
	return s
}

// mustChildMap navigates m → key and returns the value as a mapping.
func mustChildMap(t *testing.T, m yamlMap, key string) yamlMap {
	t.Helper()
	cm, err := childMap(m, key)
	if err != nil {
		t.Fatalf("key %q: %v", key, err)
	}
	return cm
}

// mustChildList navigates m → key and returns the value as a list.
func mustChildList(t *testing.T, m yamlMap, key string) []any {
	t.Helper()
	l, err := childList(m, key)
	if err != nil {
		t.Fatalf("key %q: %v", key, err)
	}
	return l
}

// mustListItem navigates to one item of a list and returns it as a
// mapping.
func mustListItem(t *testing.T, l []any, i int, path string) yamlMap {
	t.Helper()
	v, err := listItem(l, i, path)
	if err != nil {
		t.Fatalf("%s: %v", path, err)
	}
	m, ok := v.(yamlMap)
	if !ok {
		t.Fatalf("%s is not a mapping", path)
	}
	return m
}

// TestChartYAMLNamesTheServiceAndCarriesTheVersionTheApplicationPins
// holds the seam between the chart and the substrate's Application:
// kit's static manifest (templates/substrate/manifests/applications/
// identity.yaml) syncs chart identity at targetRevision 0.1.0 from the
// OCI registry, so the chart's name and version are the two facts that
// decide whether the sync finds this chart at all.
func TestChartYAMLNamesTheServiceAndCarriesTheVersionTheApplicationPins(t *testing.T) {
	root := chartRoot(t)
	doc := mustParse(t, root, "Chart.yaml")

	if name := mustChild(t, doc, "name"); name != "identity" {
		t.Errorf("Chart.yaml name is %q, want %q — the chart the Application "+
			"syncs is named after the service, the repository and the "+
			"namespace, all of which are identity", name, "identity")
	}
	if version := mustChild(t, doc, "version"); version != "0.1.0" {
		t.Errorf("Chart.yaml version is %q, want %q — the substrate's "+
			"Application pins targetRevision 0.1.0, the chart version as "+
			"the OCI tag", version, "0.1.0")
	}
}

// TestValuesCarryTheFactsADeploymentEdits holds the deployment-time
// half: the image tag's seam to the chart version, the Ingress's
// off-by-default gate and the issuer it names, and the Service port's
// agreement with the container port.
func TestValuesCarryTheFactsADeploymentEdits(t *testing.T) {
	root := chartRoot(t)
	values := mustParse(t, root, "values.yaml")
	chartYAML := mustParse(t, root, "Chart.yaml")

	t.Run("the image tag is the chart version and never latest", func(t *testing.T) {
		image := mustChildMap(t, values, "image")
		tag := mustChild(t, image, "tag")
		if tag == "latest" {
			t.Errorf("image.tag is %q — a floating tag is a deploy that "+
				"changes when somebody else pushes, and the pull-based "+
				"loop exists so that what runs is exactly what the values "+
				"commit said", tag)
		}
		version := mustChild(t, chartYAML, "version")
		if tag != version {
			t.Errorf("image.tag is %q but Chart.yaml version is %q — the "+
				"default tag is the chart's own version, and the two are "+
				"kept equal so a release bumps both by editing one file",
				tag, version)
		}
	})

	t.Run("the ingress routes auth.anywaye.com with TLS via letsencrypt-prod", func(t *testing.T) {
		ingress := mustChildMap(t, values, "ingress")
		if enabled := mustChild(t, ingress, "enabled"); enabled != "true" {
			t.Errorf("ingress.enabled is %q, want %q — identity's OIDC discovery and JWKS must be reachable on auth.anywaye.com; the issuer is baked into every token and verifiers fetch it at the issuer origin",
				enabled, "true")
		}
		if host := mustChild(t, ingress, "host"); host != "auth.anywaye.com" {
			t.Errorf("ingress.host is %q, want %q — the OIDC issuer host that verifiers fetch for discovery and JWKS",
				host, "auth.anywaye.com")
		}
		if issuer := mustChild(t, ingress, "clusterIssuer"); issuer != "letsencrypt-prod" {
			t.Errorf("ingress.clusterIssuer is %q, want %q — the "+
				"ClusterIssuer the substrate's install step 7 declares "+
				"(DEPLOYMENT.md, \"The ACME solver\"); the chart names it "+
				"and never creates it", issuer, "letsencrypt-prod")
		}
		if tls := mustChild(t, ingress, "tls"); tls != "true" {
			t.Errorf("ingress.tls is %q, want %q — the OIDC issuer is https and the Ingress must request a certificate via cert-manager",
				tls, "true")
		}
		if path := mustChild(t, ingress, "path"); path != "/" {
			t.Errorf("ingress.path is %q, want %q — discovery and JWKS live at /.well-known/*, so the Ingress must route /", path, "/")
		}
		if pathType := mustChild(t, ingress, "pathType"); pathType != "Prefix" {
			t.Errorf("ingress.pathType is %q, want %q — matching gateway and parlor's Ingress (Prefix on /)", pathType, "Prefix")
		}
	})

	t.Run("the service port agrees with the container port", func(t *testing.T) {
		service := mustChildMap(t, values, "service")
		if port := mustChild(t, service, "port"); port != "8080" {
			t.Errorf("service.port is %q, want %q — the port MUST agree "+
				"with the container port the generator baked into the "+
				"Deployment (8080, from the Go language table and from the "+
				"Dockerfile's EXPOSE): a Service that forwards to a "+
				"different port than the container listens on is a Service "+
				"that routes to nothing", port, "8080")
		}
	})

	t.Run("the secret is named and never inlined", func(t *testing.T) {
		if name := mustChild(t, values, "secretName"); name != "identity-secrets" {
			t.Errorf("secretName is %q, want %q", name, "identity-secrets")
		}
		// The secret's KEYS are enumerated in this file's comments (the
		// deployment-time half is meant to be read, and courier's chart
		// documents its secrets the same way); what this asserts is the
		// other half of the rule — that no credential reached the values
		// file itself. The generator's own header says the same thing,
		// and a credential in this file is a credential in a git
		// repository. Comments are stripped before the search, because
		// documenting a secret's NAME is not inlining its VALUE.
		data, err := os.ReadFile(filepath.Join(root, "values.yaml"))
		if err != nil {
			t.Fatalf("read values.yaml: %v", err)
		}
		for _, secret := range []string{
			"DATABASE_URL",
			"SIGNUP_SIGNING_KEY",
			"OIDC_SIGNING_KEY",
			"MFA_ENCRYPTION_KEY",
			"COURIER_TOKEN",
		} {
			for _, line := range strings.Split(string(data), "\n") {
				code := stripComment(line)
				if strings.Contains(code, secret+"=") || strings.Contains(code, secret+":") {
					t.Errorf("values.yaml inlines %s (line %q) — every secret "+
						"is a NAME in identity-secrets, loaded via envFrom; a "+
						"value here is a credential in git", secret, line)
					break
				}
			}
		}
	})
}

// TestTheDeploymentServesThePortTheDockerfileExposesAndReadyz holds the
// two facts the rollout waits on: the container port and the readiness
// path. The port is cross-checked against the Dockerfile's EXPOSE, so a
// chart whose port disagrees with the image it deploys is red rather
// than a finding somebody reports later.
func TestTheDeploymentServesThePortTheDockerfileExposesAndReadyz(t *testing.T) {
	root := chartRoot(t)
	deployment := mustParse(t, root, "templates/deployment.yaml")

	containers := mustChildList(t, mustChildMap(t,
		mustChildMap(t, mustChildMap(t, deployment, "spec"), "template"), "spec"), "containers")
	container := mustListItem(t, containers, 0, "spec.template.spec.containers[0]")

	t.Run("the container port is the Dockerfile's EXPOSE", func(t *testing.T) {
		ports := mustChildList(t, container, "ports")
		port := mustChild(t, mustListItem(t, ports, 0, "containers[0].ports[0]"), "containerPort")
		if port != "8080" {
			t.Errorf("containerPort is %q, want %q — the Go language "+
				"table's port, and the Dockerfile's EXPOSE", port, "8080")
		}
		exposed := dockerfileExpose(t)
		if port != exposed {
			t.Errorf("containerPort is %q but the Dockerfile EXPOSEs %q — "+
				"the chart deploys an image that listens on a different "+
				"port than the one the rollout's Service forwards to",
				port, exposed)
		}
	})

	t.Run("the readiness path is the fleet's contract", func(t *testing.T) {
		probe := mustChildMap(t, mustChildMap(t, container, "readinessProbe"), "httpGet")
		if path := mustChild(t, probe, "path"); path != "/readyz" {
			t.Errorf("readiness path is %q, want %q — every anywaye "+
				"service serves /readyz and the substrate's rollout waits "+
				"on it; /healthz is the wrong answer (it answers "+
				"\"the process is up\" before the service can serve), and "+
				"a readiness path that can be edited is a defect waiting",
				path, "/readyz")
		}
	})

	t.Run("the image is named from values, by digest when there is one", func(t *testing.T) {
		// Read off the raw template, not through the parsed container
		// above: the image line is a conditional, and the file reader
		// SKIPS Helm action lines, so navigating to containers[0].image
		// sees only the last branch it parsed — the tag path — while the
		// digest path sits in the lines it skipped. A test written that
		// way would pass on a template that had dropped the digest
		// branch entirely, which is the measured defect in miniature: a
		// values file carrying a pin the template renders never and a
		// green test reporting agreement. What this asserts is that both
		// branches are in the file and nothing is baked in; what
		// render_test.go's renders assert is that both produce the right
		// string.
		data, err := os.ReadFile(filepath.Join(root, "templates", "deployment.yaml"))
		if err != nil {
			t.Fatalf("read templates/deployment.yaml: %v", err)
		}
		tmpl := string(data)
		for _, want := range []string{
			`image: "{{ .Values.image.repository }}@{{ .Values.image.digest }}"`,
			`image: "{{ .Values.image.repository }}:{{ .Values.image.tag }}"`,
			// The refusal. A well-formed digest is what every render
			// case uses, so a template that had stopped refusing would
			// pass all of them; this is the line that says it still
			// does, in the same kit grammar (sha256: plus 64 lowercase
			// hex) the pin-the-image-by-digest step refuses against.
			"regexMatch `^sha256:[0-9a-f]{64}$` .Values.image.digest",
		} {
			if !strings.Contains(tmpl, want) {
				t.Errorf("templates/deployment.yaml does not carry %q — "+
					"the Deployment names its image from values in both "+
					"directions (repository@digest when values carry one, "+
					"the committed repository:tag when they do not), and "+
					"refuses a digest that is neither", want)
			}
		}
	})
}

// TestTheServiceTargetsTheContainersNamedPort holds the third seam: the
// Service's targetPort is the container's named `http` port, so the
// container port and the Service document cannot disagree — a numeric
// targetPort here would be a second place to hold the port, and the
// second place is the one that drifts.
func TestTheServiceTargetsTheContainersNamedPort(t *testing.T) {
	root := chartRoot(t)
	service := mustParse(t, root, "templates/service.yaml")

	ports := mustChildList(t, mustChildMap(t, service, "spec"), "ports")
	port := mustListItem(t, ports, 0, "spec.ports[0]")
	target, err := child(port, "targetPort")
	if err != nil {
		t.Fatalf("spec.ports[0].targetPort: %v", err)
	}
	if target != "http" {
		t.Errorf("spec.ports[0].targetPort is %q, want %q — the "+
			"container's named port, so the Service and the Deployment "+
			"cannot disagree about the port", target, "http")
	}
}

// TestTheChartShipsNoApplication holds the line DEPLOYMENT.md draws:
// the substrate owns the Argo Application, one per service, and a
// service repository does not commit one. The generator still emits
// templates/application.yaml (a git source, path: chart) — the same
// collision as a hand-written one, generated — so this assertion is
// what fails if the file is ever regenerated or re-added. The caf-side
// fix is a caf packet; this repository deletes the file and reports it.
func TestTheChartShipsNoApplication(t *testing.T) {
	root := chartRoot(t)

	if _, err := os.Stat(filepath.Join(root, "templates", "application.yaml")); !os.IsNotExist(err) {
		t.Errorf("chart/templates/application.yaml exists — the substrate " +
			"owns the Application (kit's static manifest, OCI source, " +
			"targetRevision 0.1.0); two Applications of one name and " +
			"namespace with different sources fight, and the later apply " +
			"wins. Delete the file; the generator's emission of it is a " +
			"caf-side bug, tracked as the caf packet that removes it")
	}

	for _, name := range KeptFiles {
		if _, err := os.Stat(filepath.Join(root, filepath.FromSlash(name))); err != nil {
			t.Errorf("chart/%s: %v — the chart is missing a file it ships", name, err)
		}
	}
}

// TestTheIngressTemplateIsGatedOnTheValue holds the off-by-default gate
// in the template itself, not only in values: the whole document sits
// inside `{{- if .Values.ingress.enabled }}`, so a default-on Ingress is
// a red test rather than a surprise in the cluster.
func TestTheIngressTemplateIsGatedOnTheValue(t *testing.T) {
	root := chartRoot(t)
	data, err := os.ReadFile(filepath.Join(root, "templates", "ingress.yaml"))
	if err != nil {
		t.Fatalf("read templates/ingress.yaml: %v", err)
	}
	if !strings.Contains(string(data), "{{- if .Values.ingress.enabled }}") {
		t.Errorf("templates/ingress.yaml is not gated on " +
			".Values.ingress.enabled — with the gate missing the " +
			"Ingress renders on every sync, host or no host")
	}
}

// dockerfileExpose returns the port the Dockerfile EXPOSEs, failing the
// test if there is none.
func dockerfileExpose(t *testing.T) string {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(chartRoot(t), "..", "Dockerfile"))
	if err != nil {
		t.Fatalf("read Dockerfile: %v", err)
	}
	for _, line := range strings.Split(string(data), "\n") {
		fields := strings.Fields(line)
		if len(fields) == 2 && fields[0] == "EXPOSE" {
			return fields[1]
		}
	}
	t.Fatalf("Dockerfile has no EXPOSE line — the chart's container port " +
		"has nothing to be checked against")
	return ""
}
